import { useState, useEffect, useCallback, useRef } from 'react';
import { apiClient } from '../api/client';

/**
 * useAnomalies Hook
 * Fetches ML anomaly detection results generated by Isolation Forest and PCA pipelines.
 *
 * @param {Object} options
 * @param {number} options.pollIntervalMs Polling frequency in ms.
 * @param {string} options.nodeId Target node identifier.
 * @param {number} options.limit Number of flagged records to retrieve.
 */
export function useAnomalies({
  pollIntervalMs = 10000,
  nodeId = 'node1',
  limit = 50
} = {}) {
  const [anomalies, setAnomalies] = useState([]);
  const [latestAnomalyResult, setLatestAnomalyResult] = useState(null);
  const [detectorMetadata, setDetectorMetadata] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const isMountedRef = useRef(true);

  const fetchAnomalies = useCallback(async () => {
    try {
      // Calls Isolation Forest / PCA anomaly evaluation endpoint
      const response = await apiClient.get('/predictive/anomalies', {
        params: { node_id: nodeId, limit }
      });

      if (!isMountedRef.current) return;

      const data = response?.data || {};

      // Flagged observation records
      const flagged = Array.isArray(data.flagged_records)
        ? data.flagged_records
        : Array.isArray(data.anomalies)
        ? data.anomalies
        : [];

      // Latest observation score and decision
      const latestEval = data.latest_evaluation || {
        is_anomaly: data.is_anomaly ?? (flagged.length > 0 && flagged[0]?.is_anomaly),
        score: data.current_score ?? flagged[0]?.anomaly_score ?? null,
        pca_residual: data.pca_reconstruction_error ?? null,
        detector: data.detector_used || 'IsolationForest'
      };

      setAnomalies(flagged);
      setLatestAnomalyResult(latestEval);
      setDetectorMetadata(data.detector_metadata || null);
      setError(null);
    } catch (err) {
      if (!isMountedRef.current) return;
      const msg = err.response?.data?.detail || err.message || 'Failed to fetch anomaly detection outputs';
      setError(msg);
    } finally {
      if (isMountedRef.current) {
        setLoading(false);
      }
    }
  }, [nodeId, limit]);

  useEffect(() => {
    isMountedRef.current = true;
    fetchAnomalies();

    let intervalId = null;
    if (pollIntervalMs > 0) {
      intervalId = setInterval(fetchAnomalies, pollIntervalMs);
    }

    return () => {
      isMountedRef.current = false;
      if (intervalId) clearInterval(intervalId);
    };
  }, [fetchAnomalies, pollIntervalMs]);

  const refetch = useCallback(() => {
    setLoading(true);
    return fetchAnomalies();
  }, [fetchAnomalies]);

  return {
    anomalies,
    latestAnomalyResult,
    detectorMetadata,
    loading,
    error,
    refetch
  };
}